def is_priority_inverted(job_i, current_time, scheduled_jobs, m):
    if not job_i.is_pending(current_time) or job_i.is_scheduled(current_time):
        return False

    higher_priority_scheduled_count = 0
    for scheduled_job in scheduled_jobs:
        if scheduled_job.base_priority < job_i.base_priority:
            higher_priority_scheduled_count += 1

    return higher_priority_scheduled_count < m

def classify_delay(job_i, job_x, job_a, resource_q_held_by_x, resource_u_waiting_for_i, current_time, m):
    is_i_pending_not_scheduled = job_i.is_pending(current_time) and not job_i.is_scheduled(current_time)
    num_higher_base_priority_scheduled = count_higher_base_priority_scheduled(job_i, current_time)

    # Direct pi-blocking
    if is_i_pending_not_scheduled and job_i.is_waiting_for_resource(resource_q_held_by_x) and num_higher_base_priority_scheduled < m:
        return 'direct_pi_blocking'

    # Assuming J_x is scheduled, J_i is pending, not scheduled, and not directly blocked
    if not job_x.is_scheduled(current_time) or not is_i_pending_not_scheduled or job_i.is_waiting_for_resource(resource_q_held_by_x):
        return 'other_delay_or_no_delay' # Or handle other cases not covered by the 'interference' definitions

    # Regular interference
    if job_x.base_priority < job_i.base_priority:
        return 'regular_interference'

    # Cases where job_x.base_priority > job_i.base_priority
    if job_x.effective_priority(current_time) < job_i.base_priority:
        # Co-boosting interference
        if not job_x.is_holding_resource(current_time):
            return 'co_boosting_interference'
        # Indirect pi-blocking (J_i suspended, J_a not scheduled)
        elif job_i.is_suspended(current_time) and job_i.is_waiting_for_resource(resource_u_waiting_for_i) and not job_a.is_scheduled(current_time):
            return 'indirect_pi_blocking'
        # Preemption pi-blocking (J_i ready)
        elif job_i.is_ready(current_time):
            return 'preemption_pi_blocking'

    # Stalling interference
    if job_x.effective_priority(current_time) >= job_i.base_priority:
        return 'stalling_interference'

    return 'unknown_delay_type'

def calculate_blocking_fraction(actual_blocking_time, max_critical_section_length):
    if max_critical_section_length == 0:
        return 0.0 # Or handle error if expected to be positive
    blocking_fraction = actual_blocking_time / max_critical_section_length
    return min(1.0, max(0.0, blocking_fraction)) # Ensure it's within [0, 1]

def get_max_contested_holding_time(task_x, resource_q, task_i_waiting):
    if task_x.num_accesses_to_resource(resource_q) == 0:
        return 0
    # This value is typically computed by protocol-specific lemmas (e.g., Lemma 8, 9, 10)
    # For example, for PI, it might involve solving a recurrence relation.
    # For RSB, it might be a direct sum of critical section lengths.
    return calculate_protocol_specific_H_x_q(task_x, resource_q, task_i_waiting)

def check_delay_exclusivity(job_i, current_time, delay_types_incurred):
    if 'direct_pi_blocking' in delay_types_incurred:
        # If direct pi-blocking is present, no other delay type should be present for job_i at current_time
        for delay_type in delay_types_incurred:
            if delay_type != 'direct_pi_blocking':
                return False # Contradiction
    return True

def calculate_response_time_bound(task_i_wcet, OD_i_value, B_D_map_for_i, task_set_minus_i):
    R_i = task_i_wcet + OD_i_value
    for task_x in task_set_minus_i:
        R_i += B_D_map_for_i.get(task_x, 0) # B_D_map_for_i stores B_D_x for each x
    return R_i

def constraint_total_workload_bound(task_x, R_i, N_i_x_q_map, L_x_q_map, X_D_map, X_I_map, X_P_map, I_R_x, I_C_x, I_S_x, W_x_R_i_func):
    total_blocking_from_x = 0
    for q in all_resources:
        for v in range(1, N_i_x_q_map.get((task_x, q), 0) + 1):
            total_blocking_from_x += L_x_q_map.get((task_x, q), 0) * (
                X_D_map.get((task_x, q, v), 0) + 
                X_I_map.get((task_x, q, v), 0) + 
                X_P_map.get((task_x, q, v), 0)
            )

    total_interference_from_x = I_R_x + I_C_x + I_S_x

    lhs = total_blocking_from_x + total_interference_from_x
    rhs = W_x_R_i_func(R_i, task_x.period, task_x.deadline, task_x.wcet) # Using Def 3

    return lhs <= rhs

def constraint_no_direct_blocking_unrequested_resources(task_i, all_resources, N_i_q_map, X_D_map):
    for q in all_resources:
        if N_i_q_map.get((task_i, q), 0) == 0: # If task_i does not request resource q
            # Then for any task_x and any request v, X_D_x_q_v must be 0
            for task_x in all_tasks:
                for v in range(1, N_i_x_q_map.get((task_x, q), 0) + 1): # N_i_x_q is for T_x's requests
                    if X_D_map.get((task_x, q, v), 0) != 0:
                        return False # Violation
    return True

def verify_unique_effective_priorities(ready_jobs_list, protocol_is_PI_based):
    if not protocol_is_PI_based:
        return True # Lemma only applies to PI-based protocols

    effective_priorities_seen = set()
    for job in ready_jobs_list:
        eff_prio = job.get_effective_priority() # This function would implement PI rules
        if eff_prio in effective_priorities_seen:
            return False # Contradiction: effective priorities are not unique
        effective_priorities_seen.add(eff_prio)
    return True

def verify_scheduled_priorities_on_delay(job_i, current_time, scheduled_jobs, m, protocol_is_PI_based):
    if not protocol_is_PI_based:
        return True # Lemma only applies to PI-based protocols

    # Assume job_i incurs indirect or preemption pi-blocking

    for scheduled_job in scheduled_jobs:
        if scheduled_job.get_effective_priority() <= job_i.base_priority:
            return False # Contradiction: a scheduled job has lower or equal effective priority

    return True

def constraint_no_co_boosting_under_PI(task_x, I_C_x_value, protocol_is_PI_based):
    if protocol_is_PI_based:
        return I_C_x_value == 0
    return True

def constraint_top_m_tasks_delay_invariance(task_x, m, I_S_x_value, B_I_x_value, B_P_x_value, protocol_is_PI_based):
    if protocol_is_PI_based and task_x.base_priority <= m:
        return (I_S_x_value + B_I_x_value + B_P_x_value) == 0
    return True

def constraint_fifo_direct_blocking(task_i, task_x, resource_q, N_i_x_q_map, X_D_map, protocol_uses_fifo):
    if protocol_uses_fifo:
        total_direct_blocking_fractions_from_x_for_q = 0
        for v in range(1, N_i_x_q_map.get((task_x, q), 0) + 1):
            total_direct_blocking_fractions_from_x_for_q += X_D_map.get((task_x, q, v), 0)
        return total_direct_blocking_fractions_from_x_for_q <= 1.0
    return True

def calculate_H_x_q_PI(task_x, task_i, resource_q, m, L_x_q_value, task_set, W_func, eta_func, N_l_u_map, L_l_u_map, Pi_func):
    x = task_x.base_priority
    i = task_i.base_priority

    if x <= m:
        return L_x_q_value
    else:
        y = min(x, i)
        z = max(x, i)

        # Initial guess for H_x_q (e.g., L_x_q)
        H_x_q_current = L_x_q_value
        H_x_q_next = 0

        while True:
            sum_regular_interference = 0
            for task_h in task_set:
                if task_h.base_priority < y:
                    sum_regular_interference += W_func(H_x_q_current, task_h.period, task_h.deadline, task_h.wcet)

            sum_preemption_pi_blocking = 0
            for task_l in task_set:
                if task_l.base_priority > y and task_l.base_priority != z:
                    for resource_u in all_resources:
                        if N_l_u_map.get((task_l, resource_u), 0) > 0 and Pi_func(resource_u) < y: # Corrected N_l_u > 0
                            L_x_q_l_u_val = eta_func(H_x_q_current, task_l.wcrt, task_l.period) * N_l_u_map.get((task_l, resource_u), 0) * L_l_u_map.get((task_l, resource_u), 0)
                            sum_preemption_pi_blocking += L_x_q_l_u_val

            H_x_q_next = L_x_q_value + (1.0 / m) * (sum_regular_interference + sum_preemption_pi_blocking)

            if abs(H_x_q_next - H_x_q_current) < epsilon: # Convergence check
                return H_x_q_next

            H_x_q_current = H_x_q_next

def calculate_H_x_q_RSB(task_x, task_i, resource_q, L_x_q_value, task_set, L_a_u_map):
    sum_other_cs_lengths = 0
    for task_a in task_set:
        if task_a != task_x and task_a != task_i:
            max_L_a_u_for_other_resources = 0
            for resource_u in all_resources:
                if resource_u != resource_q:
                    max_L_a_u_for_other_resources = max(max_L_a_u_for_other_resources, L_a_u_map.get((task_a, resource_u), 0))
            sum_other_cs_lengths += max_L_a_u_for_other_resources

    H_x_q = L_x_q_value + sum_other_cs_lengths
    return H_x_q
